<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/config.php';
exigirAdmin();

$erro='';$sucesso='';$editarId=max(0,(int)($_GET['editar']??$_POST['area_id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){$acao=(string)($_POST['acao']??'salvar');if(!validarCsrf($_POST['csrf_token']??null)){$erro='A solicitação expirou. Atualize a página.';}else{try{if($acao==='excluir'){$stmt=$pdo->prepare('SELECT COUNT(*) FROM treinamentos WHERE area_id=?');$stmt->execute([$editarId]);if((int)$stmt->fetchColumn()>0){$erro='Esta área possui treinamentos e não pode ser removida.';}else{$stmt=$pdo->prepare('SELECT nome FROM areas WHERE id=?');$stmt->execute([$editarId]);$nome=$stmt->fetchColumn();$stmt=$pdo->prepare('DELETE FROM areas WHERE id=?');$stmt->execute([$editarId]);if($nome!==false){registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'removeu a área',(string)$nome);}$sucesso='Área removida.';$editarId=0;}}else{$nome=trim((string)($_POST['nome']??''));$descricao=trim((string)($_POST['descricao']??''));$cor=strtoupper(trim((string)($_POST['cor']??'#3B4E7A')));if(mb_strlen($nome)<2||!preg_match('/^#[0-9A-F]{6}$/',$cor)){$erro='Informe um nome e uma cor válida.';}elseif($editarId){$stmt=$pdo->prepare('UPDATE areas SET nome=?,descricao=?,cor=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?');$stmt->execute([$nome,$descricao,$cor,$editarId]);registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'editou a área',$nome);$sucesso='Área atualizada.';}else{$stmt=$pdo->prepare('INSERT INTO areas (nome,descricao,cor) VALUES (?,?,?)');$stmt->execute([$nome,$descricao,$cor]);registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'criou a área',$nome);$sucesso='Área cadastrada.';}}}catch(Throwable $e){registrarErro($pdo,'gerenciamento de areas',$e);$erro='Não foi possível concluir a operação.';}}}
$areas=$pdo->query('SELECT a.*,COUNT(t.id) AS total_treinamentos FROM areas a LEFT JOIN treinamentos t ON t.area_id=a.id GROUP BY a.id ORDER BY a.nome')->fetchAll();$edicao=['nome'=>'','descricao'=>'','cor'=>'#3B4E7A'];if($editarId){$stmt=$pdo->prepare('SELECT * FROM areas WHERE id=?');$stmt->execute([$editarId]);$edicao=$stmt->fetch()?:$edicao;}
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TrainHub - Áreas</title><link rel="stylesheet" href="css/app.css?v=1.0"><style>.area-cor{width:12px;height:42px;border-radius:6px;background:var(--cor);flex:0 0 auto}</style></head><body><header class="th-topbar"><a class="th-logo" href="dashboard.php"><img src="assets/logo.png" alt="TrainHub"></a><a class="th-avatar" href="perfil.php">●</a></header><main class="th-shell"><a class="th-back" href="dashboard.php">←</a><div class="th-heading"><div><h1>Áreas</h1><p>Organize os treinamentos por área de conhecimento.</p></div></div><?php if($erro):?><p class="th-alert th-alert-error"><?php echo esc($erro);?></p><?php endif;?><?php if($sucesso):?><p class="th-alert th-alert-success"><?php echo esc($sucesso);?></p><?php endif;?><div class="th-grid"><section class="th-panel"><h2>Áreas cadastradas</h2><div class="th-list"><?php foreach($areas as $area):?><article class="th-card th-card-row" style="--cor:<?php echo esc($area['cor']);?>"><span class="area-cor"></span><div style="flex:1"><strong><?php echo esc($area['nome']);?></strong><p class="th-meta"><?php echo esc($area['descricao']?:'Sem descrição.');?> · <?php echo (int)$area['total_treinamentos'];?> treinamentos</p></div><a class="th-button" href="areas.php?editar=<?php echo (int)$area['id'];?>">Editar</a></article><?php endforeach;?></div></section><aside class="th-panel"><h2><?php echo $editarId?'Editar área':'Nova área';?></h2><form class="th-form" method="post"><?php echo csrfInput();?><input type="hidden" name="acao" value="salvar"><input type="hidden" name="area_id" value="<?php echo $editarId;?>"><label class="th-field">Nome<input name="nome" maxlength="100" value="<?php echo esc($edicao['nome']);?>" required></label><label class="th-field">Descrição<textarea name="descricao"><?php echo esc($edicao['descricao']);?></textarea></label><label class="th-field">Cor<input name="cor" type="color" value="<?php echo esc($edicao['cor']);?>"></label><button class="th-button"><?php echo $editarId?'Salvar alterações':'Cadastrar área';?></button></form><?php if($editarId):?><form method="post" style="margin-top:10px" onsubmit="return confirm('Remover esta área?')"><?php echo csrfInput();?><input type="hidden" name="acao" value="excluir"><input type="hidden" name="area_id" value="<?php echo $editarId;?>"><button class="th-button th-button-danger">Remover área</button></form><a class="th-button th-button-secondary" style="margin-top:10px" href="areas.php">Cancelar edição</a><?php endif;?></aside></div></main></body></html>
